// ─── MLS PDF Parser (client-side) ─────────────────────────────────────────────
// Works with CCAR, bridgeMLS, Bay East and other MLS formats
// Uses position-aware reconstruction to handle any table layout
async function parseMlsPdf(file) {
  const arrayBuffer = await file.arrayBuffer();
  const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;

  // Position-aware text reconstruction
  // Groups items by Y position (line), sorts by X within each line
  let lineMap = {};

  for (let pageNum = 1; pageNum <= pdf.numPages; pageNum++) {
    const page = await pdf.getPage(pageNum);
    const viewport = page.getViewport({ scale: 1.0 });
    const content = await page.getTextContent({ normalizeWhitespace: true });

    content.items.forEach(item => {
      if (!item.str || item.str.trim() === "") return;
      const x = Math.round(item.transform[4]);
      const y = Math.round(viewport.height - item.transform[5]);
      const lineKey = Math.round(y / 5) * 5;
      if (!lineMap[lineKey]) lineMap[lineKey] = [];
      lineMap[lineKey].push({ x, str: item.str.trim() });
    });
  }

  const sortedLines = Object.keys(lineMap).map(Number).sort((a, b) => a - b);
  const lines = sortedLines.map(y => {
    const items = lineMap[y].sort((a, b) => a.x - b.x);
    return items.map(i => i.str).join(" ");
  });

  const fullText = lines.join("\n");
  // Normalize common MLS formatting variations
  const normText = fullText
    .replace(/([A-Za-z]):([\$\d])/g, '$1: $2')
    .replace(/MLS#:([\d]+)/g, 'MLS# $1')
    .replace(/\s{2,}/g, ' ')
    .trim();

  const allText = lines.join(" ");

  const num = (pattern) => {
    const m = normText.match(pattern);
    if (!m) return null;
    const v = m[1].replace(/[,$\s]/g, "");
    return v ? parseFloat(v) : null;
  };
  const find = (pattern) => {
    const m = normText.match(pattern);
    return m ? m[1].replace(/[,$\s]/g, "") : null;
  };

  // Property info — search full reconstructed text
  const searchAll = (pat) => { const m = allText.match(pat); return m ? m[1].replace(/[,$\s]/g,"") : null; };
  const numAll = (pat) => { const v = searchAll(pat); return v ? parseFloat(v) : null; };
  const listPrice    = numAll(/List\s*Price:\s*\$ ?([\d,]+)/i);
  const totalUnits   = numAll(/Total\s*Units:\s*(\d+)/i);
  const buildingSqft = numAll(/Building\s*Sq\s*Ft:\s*([\d,]+)/i);
  const yearBuilt    = numAll(/Year\s*Built:\s*(\d{4})/i);
  const mlsNum       = searchAll(/MLS#\s*([\d]+)/i);

  // Address - extract from reconstructed lines directly
  // Line pattern: street on one line, "CITY CA ZIP" on next line
  let address = "", city = "", zip = "";
  for (let li = 0; li < lines.length - 1; li++) {
    const streetM = lines[li].match(/^(\d+\s+[\w\s]+?(?:Rd|St|Ave|Blvd|Dr|Ln|Way|Ct|Pl|Cir|Circle))\s*$/i);
    if (streetM) {
      const cityLineM = lines[li+1] && lines[li+1].match(/^([A-Z][A-Z\s]+?)\s+CA\s+(\d{5})/);
      if (cityLineM) {
        address = streetM[1].trim();
        city = cityLineM[1].trim();
        zip = cityLineM[2];
        break;
      }
    }
  }
  // Fallback: search normText
  if (!address) {
    const addrM = allText.match(/(\d+\s+[\w]+(?:\s+[\w]+){1,4}?\s+(?:Rd|St|Ave|Blvd|Dr|Ln|Way|Ct|Pl|Cir|Circle))\s+([A-Z][A-Z\s]+?)\s+CA\s+(\d{5})/);
    if (addrM) { address = addrM[1].trim(); city = addrM[2].trim(); zip = addrM[3]; }
  }

  // Property type
  let propType = "Residential Income";
  if (/FOURPLEX/i.test(normText)) propType = "Fourplex";
  else if (/TRIPLEX/i.test(normText)) propType = "Triplex";
  else if (/DUPLEX/i.test(normText)) propType = "Duplex";
  else if (/5\+\s*UNITS/i.test(normText)) propType = "5+ Units";
  else if (/RESIDENTIAL\s*INCOME/i.test(normText)) propType = "Residential Income";

  // Unit rent roll — flexible pattern for PDF.js token spacing
  const units = [];
  const unitPattern = /Unit\s*#?\s*([A-Z\d]+)\s+([\d,]+)\s+([\d,]+)\s+T\s+(\d+)\s+([\d.]+)/gi;
  let m;
  while ((m = unitPattern.exec(normText)) !== null) {
    const sqft = parseFloat(m[2].replace(/,/g,""));
    const rent = parseFloat(m[3].replace(/,/g,""));
    // Sanity check: sqft should be > 200, rent > 100
    if (sqft > 200 && rent > 100) {
      units.push({
        unit: m[1].toUpperCase(),
        sqft,
        monthlyRent: rent,
        beds: parseInt(m[4]),
        baths: parseFloat(m[5]),
      });
    }
  }
  const totalMonthlyRent = units.reduce((s, u) => s + u.monthlyRent, 0);

  // Financials — search entire document (PDF.js may render bottom-to-top)
  // Each line is searched independently for maximum compatibility
  const finNum = (pat) => {
    const m = allText.match(pat);
    return m ? parseFloat(m[1].replace(/[,$\s]/g,"")) : null;
  };

  const rentalIncome  = finNum(/Rental\s*Income:\s*\$ ?([\d,]+)/i);
  const annVacancy    = finNum(/Ann\s*Vacancy\s*Exp:\s*\$ ?([\d,]+)/i);
  const grossSched    = finNum(/Gross\s*Sched\s*Inc:\s*\$ ?([\d,]+)/i);
  const noi           = finNum(/Net\s*Oper\s*Inc:\s*\$ ?([\d,]+)/i);
  const annTaxes      = finNum(/Annual\s*Taxes:\s*\$ ?([\d,]+)/i);
  const annMaint      = finNum(/Ann\s*Maint(?:ance|enance)?:\s*\$ ?([\d,]+)/i);
  const annUtilities  = finNum(/Annual\s*Utilities:\s*\$ ?([\d,]+)/i);
  const annInsurance  = finNum(/Ann\s*Insurance:\s*\$ ?([\d,]+)/i);
  const listPriceAlt  = finNum(/List\s*Price:\s*\$ ?([\d,]+)/i);

  // OpEx monthly
  let monthlyOpex = 0, opexSource = "estimated";
  if (annTaxes && annInsurance && annMaint) {
    monthlyOpex = Math.round(((annTaxes||0)+(annMaint||0)+(annUtilities||0)+(annInsurance||0))/12);
    opexSource = "MLS actuals";
  } else if (totalMonthlyRent > 0) {
    monthlyOpex = Math.round(totalMonthlyRent * 0.40);
    opexSource = "CCIM estimate (40% of gross rent)";
  }

  // Vacancy rate
  let vacancyRate = 5.0, vacancySource = "CCIM estimate";
  if (annVacancy && rentalIncome && rentalIncome > 0) {
    vacancyRate = parseFloat(((annVacancy/rentalIncome)*100).toFixed(1));
    vacancySource = "MLS actuals";
  }

  const hasActuals = !!(noi || annTaxes || annInsurance);
  const completeness = hasActuals && units.length > 0 ? "FULL"
    : units.length > 0 ? "PARTIAL" : "ESTIMATED";

  return {
    address, city, zip, mlsNum, propType, listPrice,
    totalUnits, buildingSqft, yearBuilt,
    units, totalMonthlyRent,
    rentalIncome, annVacancy, grossSched, noi,
    annTaxes, annMaint, annUtilities, annInsurance,
    monthlyOpex, opexSource, vacancyRate, vacancySource,
    completeness,
  };
}

// ─── Calc Engine ──────────────────────────────────────────────────────────────
function calcMetrics({ purchasePrice, monthlyRent, downPct, mortgageRate,
  mortgageTerm, monthlyExpenses, economicVacancy, appreciationRate,
  rentGrowthRate, timeHorizon }) {
  const down = purchasePrice * (downPct/100);
  const loan = purchasePrice - down;
  const mRate = (mortgageRate/100)/12;
  const nPay = mortgageTerm*12;
  const mortgage = mRate>0 ? loan*mRate/(1-Math.pow(1+mRate,-nPay)) : loan/nPay;
  const effRent = monthlyRent*(1-economicVacancy/100);
  const annRent = effRent*12;
  const annExp = monthlyExpenses*12;
  const annMort = mortgage*12;
  const noi1 = annRent-annExp;
  const cf1 = noi1-annMort;
  const dscr = annMort ? noi1/annMort : 0;
  const capRate = purchasePrice ? (noi1/purchasePrice)*100 : 0;
  const coc = down ? (cf1/down)*100 : 0;

  const cashFlows=[], rents=[], rois=[];
  let curRent=monthlyRent;
  for (let yr=1; yr<=timeHorizon; yr++) {
    if (yr>1) curRent *= (1+rentGrowthRate/100);
    const yEff=curRent*(1-economicVacancy/100);
    const yCF=yEff*12-annExp-annMort;
    const appVal=purchasePrice*((1+appreciationRate/100)**yr-1);
    const cumCF=cashFlows.reduce((a,b)=>a+b,0)+yCF;
    const roi=down?((cumCF+appVal)/down)*100:0;
    cashFlows.push(Math.round(yCF));
    rents.push(Math.round(curRent*12));
    rois.push(Math.round(roi));
  }

  const saleVal=purchasePrice*((1+appreciationRate/100)**timeHorizon);
  const cfTotal=[...cashFlows];
  cfTotal[cfTotal.length-1]+=saleVal;

  function irrSolve(flows) {
    // Mirrors Python calc_engine.py: npf.irr → Newton → return 0 on failure
    if(!down || down < 1) return 0;
    const npv = (r) => flows.reduce((a,cf,j)=>a+cf/Math.pow(1+r,j+1),-down);
    const dnpv = (r) => flows.reduce((a,cf,j)=>a-(j+1)*cf/Math.pow(1+r,j+2),0);
    // Try Newton with multiple guesses (mirrors robust_irr with different starting points)
    for (const guess of [0.1, -0.1, 0.5, -0.5, 0.01, -0.3, -0.7, -0.9]) {
      let r = guess;
      for(let i=0;i<300;i++){
        const f=npv(r), df=dnpv(r);
        if(!isFinite(f)||!isFinite(df)||Math.abs(df)<1e-12) break;
        const step=f/df; r-=step;
        if(r<-0.9999) r=-0.9999;
        if(Math.abs(step)<1e-8){
          const pct=r*100;
          if(isFinite(pct)&&Math.abs(pct)<9999) return Math.round(pct*100)/100;
          break;
        }
      }
    }
    // Bisection fallback — handles all-negative cash flow scenarios
    let lo=-0.9999, hi=10.0;
    const nlo=npv(lo), nhi=npv(hi);
    if(nlo*nhi>0){
      // Try extended negative range
      lo=-0.9999; hi=-0.0001;
      if(npv(lo)*npv(hi)>0) return 0; // no solution — return 0 like Python
    }
    for(let i=0;i<120;i++){
      const mid=(lo+hi)/2;
      if(npv(lo)*npv(mid)<=0) hi=mid; else lo=mid;
      if(hi-lo<1e-9) break;
    }
    const pct=((lo+hi)/2)*100;
    return (isFinite(pct)&&Math.abs(pct)<9999) ? Math.round(pct*100)/100 : 0;
  }
  const irrOp=irrSolve(cashFlows);
  const irrTotal=irrSolve(cfTotal);
  const eqMult=down?cfTotal.reduce((a,b)=>a+b,0)/down:0;
  return {capRate,coc,dscr,cf1,irrOp,irrTotal,eqMult,cashFlows,rents,rois,mortgage,down};
}

// ─── Small components ─────────────────────────────────────────────────────────
const Label = ({children}) => <div style={{fontSize:11,color:C.muted,marginBottom:3}}>{children}</div>;

function SliderInput({label,value,min,max,step=1,display,onChange}) {
  return (
    <div style={{marginBottom:13}}>
      <div style={{display:"flex",justifyContent:"space-between",marginBottom:3}}>
        <span style={{fontSize:11,color:C.muted}}>{label}</span>
        <span style={{fontSize:12,fontWeight:700,color:C.goldLt}}>{display(value)}</span>
      </div>
      <input type="range" min={min} max={max} step={step} value={value}
        onChange={e=>onChange(Number(e.target.value))}
        style={{width:"100%",accentColor:C.gold,cursor:"pointer"}}/>
    </div>
  );
}

function PlusMinusInput({label,value,min,max,step=1,display,onChange,note}) {
  const [editing, setEditing] = React.useState(false);
  const [raw, setRaw] = React.useState("");
  return (
    <div style={{marginBottom:13}}>
      <Label>{label}</Label>
      <div style={{display:"flex",alignItems:"center",gap:6}}>
        <button onClick={()=>onChange(Math.max(min,value-step))}
          style={{width:28,height:28,border:`1px solid ${C.border}`,background:C.navyLt,
            color:C.gold,borderRadius:5,cursor:"pointer",fontSize:16}}>−</button>
        {editing ? (
          <input
            type="text"
            autoFocus
            value={raw}
            onChange={e=>setRaw(e.target.value)}
            onBlur={()=>{
              const parsed = parseFloat(raw.replace(/[$,%\s,]/g,""));
              if(!isNaN(parsed)) onChange(Math.min(max, Math.max(min, parsed)));
              setEditing(false);
            }}
            onKeyDown={e=>{
              if(e.key==="Enter"){
                const parsed = parseFloat(raw.replace(/[$,%\s,]/g,""));
                if(!isNaN(parsed)) onChange(Math.min(max, Math.max(min, parsed)));
                setEditing(false);
              }
              if(e.key==="Escape") setEditing(false);
            }}
            style={{flex:1,background:C.navyLt,border:`1px solid ${C.gold}`,
              borderRadius:5,padding:"5px 10px",fontSize:13,color:C.white,
              textAlign:"center",outline:"none"}}
          />
        ) : (
          <div
            onClick={()=>{setEditing(true);setRaw(String(value));}}
            title="Click to type a value"
            style={{flex:1,background:C.navyLt,border:`1px solid ${C.border}`,
              borderRadius:5,padding:"5px 10px",fontSize:13,color:C.white,
              textAlign:"center",cursor:"text"}}>
            {display(value)}
          </div>
        )}
        <button onClick={()=>onChange(Math.min(max,value+step))}
          style={{width:28,height:28,border:`1px solid ${C.border}`,background:C.navyLt,
            color:C.gold,borderRadius:5,cursor:"pointer",fontSize:16}}>+</button>
      </div>
      {note && <div style={{fontSize:10,color:C.muted,marginTop:3}}>{note}</div>}
    </div>
  );
}

function Pill({label,value,color=C.gold}) {
  return (
    <div style={{textAlign:"center",padding:"10px 14px",background:C.navyMid,
      borderRadius:10,border:`1px solid ${C.border}`,flex:"1 1 110px"}}>
      <div style={{fontSize:10,color:C.muted,textTransform:"uppercase",letterSpacing:1,marginBottom:4}}>{label}</div>
      <div style={{fontSize:20,fontWeight:700,color,fontFamily:"Georgia,serif"}}>{value}</div>
    </div>
  );
}

function DSCRBar({val}) {
  const pct=Math.min(val/3,1)*100;
  const col=val>=1.25?C.green:val>=1.0?C.gold:C.red;
  return (
    <div>
      <div style={{display:"flex",justifyContent:"space-between",fontSize:11,marginBottom:4}}>
        <span style={{color:C.muted}}>DSCR (Debt Service Coverage)</span>
        <span style={{color:col,fontWeight:700}}>{val.toFixed(2)}× {val>=1.25?"✓ Lender OK":val>=1.0?"⚠ Borderline":"✗ Below 1.0"}</span>
      </div>
      <div style={{background:C.navyLt,borderRadius:99,height:7}}>
        <div style={{width:`${pct}%`,height:"100%",background:col,borderRadius:99,transition:"width 0.4s"}}/>
      </div>
    </div>
  );
}

function MultiLineChart({cashFlows,rents,rois,timeHorizon}) {
  const W=560,H=200,PL=62,PR=55,PT=28,PB=32;
  const cW=W-PL-PR,cH=H-PT-PB;
  const allVals=[...cashFlows,...rents];
  const minV=Math.min(...allVals,0),maxV=Math.max(...allVals,1);
  const rangeV=maxV-minV||1;
  const maxROI=Math.max(...rois,1);
  const xPx=i=>PL+(i/(timeHorizon-1||1))*cW;
  const yL=v=>PT+cH-((v-minV)/rangeV)*cH;
  const yR=v=>PT+cH-(v/maxROI)*cH;
  const poly=(data,yFn,col)=>{
    const pts=data.map((v,i)=>`${xPx(i)},${yFn(v)}`).join(" ");
    return <polyline points={pts} fill="none" stroke={col} strokeWidth="2.5" strokeLinejoin="round" strokeLinecap="round"/>;
  };
  const ticks=4;
  return (
    <svg viewBox={`0 0 ${W} ${H}`} style={{width:"100%",height:"auto"}} preserveAspectRatio="xMidYMid meet">
      {[["#4A90D9","Multi-Year Cash Flow ($)"],[C.orange,"Pro Forma Rent ($/yr)"],[C.green,"ROI (%)"]].map(([col,lbl],i)=>(
        <g key={i} transform={`translate(${PL+i*182},6)`}>
          <line x1="0" y1="5" x2="16" y2="5" stroke={col} strokeWidth="2.5"/>
          <circle cx="8" cy="5" r="3" fill={col}/>
          <text x="20" y="9" style={{fontSize:9,fill:C.muted}}>{lbl}</text>
        </g>
      ))}
      {Array.from({length:ticks+1},(_,i)=>(
        <line key={i} x1={PL} y1={PT+(i/ticks)*cH} x2={W-PR} y2={PT+(i/ticks)*cH}
          stroke={C.grid} strokeWidth="1" strokeDasharray="3,3"/>
      ))}
      {Array.from({length:ticks+1},(_,i)=>{
        const v=minV+((ticks-i)/ticks)*rangeV;
        return <text key={i} x={PL-4} y={PT+(i/ticks)*cH+4} textAnchor="end"
          style={{fontSize:9,fill:C.muted}}>{Math.abs(v)>=1000?`$${Math.round(v/1000)}K`:`$${Math.round(v)}`}</text>;
      })}
      {Array.from({length:ticks+1},(_,i)=>{
        const v=((ticks-i)/ticks)*maxROI;
        return <text key={i} x={W-PR+4} y={PT+(i/ticks)*cH+4} textAnchor="start"
          style={{fontSize:9,fill:C.muted}}>{Math.round(v)}%</text>;
      })}
      {cashFlows.map((_,i)=>(i===0||i===timeHorizon-1||(timeHorizon>5&&i%2===0))&&
        <text key={i} x={xPx(i)} y={H-6} textAnchor="middle" style={{fontSize:9,fill:C.muted}}>{i+1}</text>)}
      <line x1={PL} y1={PT} x2={PL} y2={PT+cH} stroke={C.muted} strokeWidth="1"/>
      <line x1={PL} y1={PT+cH} x2={W-PR} y2={PT+cH} stroke={C.muted} strokeWidth="1"/>
      <text x={PL+cW/2} y={H-1} textAnchor="middle" style={{fontSize:9,fill:C.muted}}>Year</text>
      {poly(cashFlows,yL,"#4A90D9")}
      {poly(rents,yL,C.orange)}
      {poly(rois,yR,C.green)}
      {cashFlows.map((v,i)=><circle key={i} cx={xPx(i)} cy={yL(v)} r="3" fill="#4A90D9"/>)}
      {rents.map((v,i)=><circle key={i} cx={xPx(i)} cy={yL(v)} r="3" fill={C.orange}/>)}
      {rois.map((v,i)=><circle key={i} cx={xPx(i)} cy={yR(v)} r="3" fill={C.green}/>)}
    </svg>
  );
}

// ─── Dual Overlay Chart (both properties on one chart) ─────────────────────────
function DualMultiLineChart({cashFlowsA,cashFlowsB,rentsA,rentsB,roisA,roisB,timeHorizon}) {
  const W=900,H=260,PL=68,PR=60,PT=42,PB=32;
  const cW=W-PL-PR,cH=H-PT-PB;
  const allVals=[...cashFlowsA,...cashFlowsB,...rentsA,...rentsB];
  const minV=Math.min(...allVals,0),maxV=Math.max(...allVals,1);
  const rangeV=maxV-minV||1;
  const maxROI=Math.max(...roisA,...roisB,1);
  const xPx=i=>PL+(i/(timeHorizon-1||1))*cW;
  const yL=v=>PT+cH-((v-minV)/rangeV)*cH;
  const yR=v=>PT+cH-(v/maxROI)*cH;
  const poly=(data,yFn,col,dashed)=>{
    const pts=data.map((v,i)=>`${xPx(i)},${yFn(v)}`).join(" ");
    return <polyline points={pts} fill="none" stroke={col} strokeWidth="2.5"
      strokeDasharray={dashed?"6,4":undefined} strokeLinejoin="round" strokeLinecap="round"/>;
  };
  const ticks=4;
  const legend=[
    ["#4A90D9","Cash Flow A ($)",false],["#9CC3EA","Cash Flow B ($)",true],
    [C.orange,"Rent A ($/yr)",false],["#F7C18C","Rent B ($/yr)",true],
    [C.green,"ROI A (%)",false],["#8FE3BE","ROI B (%)",true],
  ];
  return (
    <svg viewBox={`0 0 ${W} ${H}`} style={{width:"100%",height:"auto"}} preserveAspectRatio="xMidYMid meet">
      {legend.map(([col,lbl,dashed],i)=>(
        <g key={i} transform={`translate(${PL+(i%3)*230},${i<3?6:22})`}>
          <line x1="0" y1="5" x2="16" y2="5" stroke={col} strokeWidth="2.5"
            strokeDasharray={dashed?"5,3":undefined}/>
          <text x="20" y="9" style={{fontSize:9,fill:C.muted}}>{lbl}</text>
        </g>
      ))}
      {Array.from({length:ticks+1},(_,i)=>(
        <line key={i} x1={PL} y1={PT+(i/ticks)*cH} x2={W-PR} y2={PT+(i/ticks)*cH}
          stroke={C.grid} strokeWidth="1" strokeDasharray="3,3"/>
      ))}
      {Array.from({length:ticks+1},(_,i)=>{
        const v=minV+((ticks-i)/ticks)*rangeV;
        return <text key={i} x={PL-4} y={PT+(i/ticks)*cH+4} textAnchor="end"
          style={{fontSize:9,fill:C.muted}}>{Math.abs(v)>=1000?`$${Math.round(v/1000)}K`:`$${Math.round(v)}`}</text>;
      })}
      {Array.from({length:ticks+1},(_,i)=>{
        const v=((ticks-i)/ticks)*maxROI;
        return <text key={i} x={W-PR+4} y={PT+(i/ticks)*cH+4} textAnchor="start"
          style={{fontSize:9,fill:C.muted}}>{Math.round(v)}%</text>;
      })}
      {cashFlowsA.map((_,i)=>(i===0||i===timeHorizon-1||(timeHorizon>5&&i%2===0))&&
        <text key={i} x={xPx(i)} y={H-6} textAnchor="middle" style={{fontSize:9,fill:C.muted}}>{i+1}</text>)}
      <line x1={PL} y1={PT} x2={PL} y2={PT+cH} stroke={C.muted} strokeWidth="1"/>
      <line x1={PL} y1={PT+cH} x2={W-PR} y2={PT+cH} stroke={C.muted} strokeWidth="1"/>
      <text x={PL+cW/2} y={H-1} textAnchor="middle" style={{fontSize:9,fill:C.muted}}>Year</text>
      {poly(cashFlowsA,yL,"#4A90D9",false)}
      {poly(cashFlowsB,yL,"#9CC3EA",true)}
      {poly(rentsA,yL,C.orange,false)}
      {poly(rentsB,yL,"#F7C18C",true)}
      {poly(roisA,yR,C.green,false)}
      {poly(roisB,yR,"#8FE3BE",true)}
    </svg>
  );
}

